sed -i 's/import com.google.firebase.FirebaseApp/import com.google.firebase.FirebaseApp\nimport com.google.firebase.crashlytics.FirebaseCrashlytics/' app/src/main/java/com/example/MyApplication.kt
sed -i 's/Log.e("CrashHandler", "FATAL EXCEPTION in thread: ${thread.name}", throwable)/Log.e("CrashHandler", "FATAL EXCEPTION in thread: ${thread.name}", throwable)\n            try { FirebaseCrashlytics.getInstance().recordException(throwable) } catch(e: Exception) {}/' app/src/main/java/com/example/MyApplication.kt
sed -i 's/Log.e("AppStartup", "Note on Firestore settings: ${e.message}")/Log.e("AppStartup", "Note on Firestore settings: ${e.message}")\n                try { FirebaseCrashlytics.getInstance().recordException(e) } catch(ex: Exception) {}/' app/src/main/java/com/example/MyApplication.kt
sed -i 's/Log.e("AppStartup", "CRITICAL: FirebaseApp initialization failed!", e)/Log.e("AppStartup", "CRITICAL: FirebaseApp initialization failed!", e)\n            try { FirebaseCrashlytics.getInstance().recordException(e) } catch(ex: Exception) {}/' app/src/main/java/com/example/MyApplication.kt
